args.query:
\dt api.*
\dv api.*
select table_name,column_name,data_type,is_nullable,column_default from information_schema.columns where table_schema in ('api') order by 1,ordinal_position;
select * from api.app_user;
select tgname, tgrelid::regclass, pg_get_triggerdef(oid) from pg_trigger where not tgisinternal;
select schemaname,tablename,policyname,cmd,roles,qual,with_check from pg_policies;
select relname,relrowsecurity,relforcerowsecurity,relkind from pg_class where relnamespace='api'::regnamespace and relkind in ('r','v');

select * from api.company; select * from api.status;
select proname, pg_get_functiondef(oid) from pg_proc where pronamespace='api'::regnamespace;
select grantee,table_name,privilege_type,column_name from information_schema.column_privileges where table_schema='api' and grantee in ('applicant','expert','fund_admin','anon','authenticator','PUBLIC') order by 2,1,4;
select grantee,table_name,privilege_type from information_schema.table_privileges where table_schema='api' and grantee not in ('postgres') order by 2,1;

